255	  describe("5. Endpoints: Login, Auth Me & Logout", () => {
256	    test("POST /api/auth/login - từ chối payload sai format (400 VALIDATION_FAILED)", async () => {
257	      const res = await fetch(`${baseUrl}/api/auth/login`, {
258	        method: "POST",
