338	  describe("6. Refresh Token Rotation (RTR) & Replay Attack Detection", () => {
339	    test("POST /api/auth/refresh - rotate token thành công một lần", async () => {
340	      // 1. Login để lấy RT-1
341	      const loginRes = await fetch(`${baseUrl}/api/auth/login`, {
342	        method: "POST",
343	        headers: { "Content-Type": "application/json" },
344	        body: JSON.stringify({ email: "emp@test-phase2.vn", password: "EmpPass@123" }),
345	      });
346	      const setCookie1 = loginRes.headers.get("set-cookie");
347	      const rt1 = setCookie1.match(/refreshToken=([^;]+)/)[1];
348	
349	      // 2. Refresh lần đầu bằng RT-1 -> nhận RT-2
350	      const refreshRes1 = await fetch(`${baseUrl}/api/auth/refresh`, {
351	        method: "POST",
352	        headers: { Cookie: `refreshToken=${rt1}` },
353	      });
354	      assert.equal(refreshRes1.status, 200);
355	      const refreshBody1 = await refreshRes1.json();
356	      assert.ok(refreshBody1.accessToken);
357	      assert.equal("refreshToken" in refreshBody1, false);
358	
359	      const setCookie2 = refreshRes1.headers.get("set-cookie");
360	      const rt2 = setCookie2.match(/refreshToken=([^;]+)/)[1];
361	      assert.notEqual(rt1, rt2);
362	
363	      // 3. REPLAY ATTACK: Dùng lại RT-1 đã bị rotate -> lập tức phát hiện replay và thu hồi cả family
364	      const replayRes = await fetch(`${baseUrl}/api/auth/refresh`, {
365	        method: "POST",
366	        headers: { Cookie: `refreshToken=${rt1}` },
367	      });
