369	      const replayData = await replayRes.json();
370	      assert.equal(replayData.error.code, "TOKEN_REUSED");
371	
372	      // 4. FAIL-CLOSED: RT-2 (đang hợp lệ trước đó) cũng BỊ THU HỒI theo do cùng family
373	      const successorRes = await fetch(`${baseUrl}/api/auth/refresh`, {
374	        method: "POST",
375	        headers: { Cookie: `refreshToken=${rt2}` },
376	      });
377	      assert.equal(successorRes.status, 401);
378	    });
