380	    test("Concurrent Refresh Race Condition: cả hai không tạo successor hợp lệ dùng được sau revoke", async () => {
381	      // 1. Login
382	      const loginRes = await fetch(`${baseUrl}/api/auth/login`, {
383	        method: "POST",
384	        headers: { "Content-Type": "application/json" },
385	        body: JSON.stringify({ email: "emp@test-phase2.vn", password: "EmpPass@123" }),
386	      });
387	      const setCookie = loginRes.headers.get("set-cookie");
388	      const rt = setCookie.match(/refreshToken=([^;]+)/)[1];
389	
390	      // 2. Hai request refresh đồng thời cùng RT
391	      const [resA, resB] = await Promise.all([
392	        fetch(`${baseUrl}/api/auth/refresh`, {
393	          method: "POST",
394	          headers: { Cookie: `refreshToken=${rt}` },
395	        }),
396	        fetch(`${baseUrl}/api/auth/refresh`, {
397	          method: "POST",
398	          headers: { Cookie: `refreshToken=${rt}` },
399	        }),
400	      ]);
401	
402	      const statuses = [resA.status, resB.status];
403	      // Một request có thể thắng (200) và một bị reject (401), hoặc nếu phát hiện replay thì family bị thu hồi
